    81	        map(input, |x| map(vec!["1", "2", "3"], |y| [x, y].join(""))),
    82	        expected
    83	    );
    84	}
    85	
    86	#[test]
    87	#[ignore]
    88	fn change_in_type() {
    89	    let input: Vec<&str> = vec!["1", "2", "3"];
    90	    let expected: Vec<String> = vec!["1".into(), "2".into(), "3".into()];
    91	    assert_eq!(map(input, |s| s.to_string()), expected);
    92	}
    93	
    94	#[test]
    95	#[ignore]
    96	fn mutating_closure() {
    97	    let mut counter = 0;
    98	    let input = vec![-2, 3, 4, -5];
    99	    let expected = vec![2, 3, 4, 5];
   100	    let result = map(input, |x: i64| {
   101	        counter += 1;
   102	        x.abs()
   103	    });
