   105	    assert_eq!(counter, 4);
   106	}
   107	
   108	#[test]
   109	#[ignore]
   110	fn minimal_bounds_on_input_and_output() {
   111	    // must be able to accept arbitrary input and output types
   112	    struct Foo;
   113	    struct Bar;
   114	    map(vec![Foo], |_| Bar);
   115	}
"
